// === ESTRUCTURA DEL PATRÓN FACTORY METHOD ===

// 1. Interfaz Producto
interface Logger {
  log(message: string): void;
}

// 2. Productos Concretos
class ConsoleLogger implements Logger {
  log(message: string) {
    console.log(`[DEV] ${message}`);
  }
}

class FileLogger implements Logger {
  log(message: string) {
    // Escribe a archivo
    fs.appendFileSync('app.log', message);
  }
}

class CloudLogger implements Logger {
  log(message: string) {
    // Envía a servicio cloud
    fetch('https://logs.api.com', { method: 'POST', body: message });
  }
}

// 3. Creador (con Factory Method)
abstract class LogManager {
  // Este es el Factory Method
  abstract createLogger(): Logger;

  // El Creador también puede tener lógica que usa el producto
  logError(message: string) {
    const logger = this.createLogger();
    logger.log(`ERROR: ${message}`);
  }
}

// 4. Creadores Concretos
class DevLogManager extends LogManager {
  createLogger(): Logger {
    return new ConsoleLogger();
  }
}

class ProdLogManager extends LogManager {
  createLogger(): Logger {
    return new FileLogger();
  }
}

// Uso:
const manager = getEnvironment() === 'production'
  ? new ProdLogManager()
  : new DevLogManager();

manager.logError('Algo salió mal');
// Sin saber qué logger está usando!

